package dev.thillainirmal.cloudpulse;
import com.fasterxml.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.regex.Pattern;
@Component
public class PrometheusGateway {
 private static final Pattern LABEL=Pattern.compile("[a-zA-Z0-9_.-]{1,63}"); private final RestClient http; private final String baseUrl;
 public PrometheusGateway(RestClient.Builder builder,@Value("${cloudpulse.prometheus-url:http://localhost:9090}")String baseUrl){this.http=builder.build();this.baseUrl=baseUrl;}
 public PulseAnalyzer.Snapshot snapshot(String namespace,String workload){validate(namespace);validate(workload);String selector="namespace=\""+namespace+"\",pod=~\""+workload+".*\"";double cpu=query("sum(rate(container_cpu_usage_seconds_total{"+selector+",container!=\"\"}[5m])) * 100");double memory=query("100 * sum(container_memory_working_set_bytes{"+selector+",container!=\"\"}) / clamp_min(sum(kube_pod_container_resource_limits{"+selector+",resource=\"memory\"}), 1)");double errors=query("100 * sum(rate(http_server_requests_seconds_count{namespace=\""+namespace+"\",status=~\"5..\"}[5m])) / clamp_min(sum(rate(http_server_requests_seconds_count{namespace=\""+namespace+"\"}[5m])), 0.000001)");double latency=query("1000 * histogram_quantile(0.95, sum by(le) (rate(http_server_requests_seconds_bucket{namespace=\""+namespace+"\"}[5m])))");int restarts=(int)Math.round(query("sum(kube_pod_container_status_restarts_total{"+selector+"})"));return new PulseAnalyzer.Snapshot(namespace,workload,cpu,memory,errors,(int)Math.round(latency),restarts);}
 double query(String promql){JsonNode body=http.get().uri(baseUrl+"/api/v1/query?query={query}",promql).retrieve().body(JsonNode.class);if(body==null||!"success".equals(body.path("status").asText()))throw new IllegalStateException("Prometheus query failed");JsonNode results=body.at("/data/result");if(!results.isArray()||results.isEmpty())return 0;return Double.parseDouble(results.get(0).at("/value/1").asText("0"));}
 private void validate(String value){if(value==null||!LABEL.matcher(value).matches())throw new IllegalArgumentException("Invalid Kubernetes label value");}
}
